on conflict (slug) do nothing;

select it.id, it.base_value, now()
from public.item_types it
where it.slug in (
'iphone-se-2020-used','iphone-11-used','iphone-xr-used','iphone-8-used','galaxy-note10-used','galaxy-a52-used','pixel-6a-used','android-midrange-used',
'macbook-pro-13-2019-used','thinkpad-t480-used','dell-latitude-5420-used','hp-elitebook-840-g7-used','acer-nitro-5-used','asus-vivobook-15-used','chromebook-14-used','office-pc-set-used',
'switch-v2-used','switch-dock-set-used','xbox-one-s-used','playstation-4-slim-used','wireless-gamepad-used','pc-gamepad-retro-used','game-boy-original-used','second-controller-used',
'running-shoes-used','room-shoe-lot-used','mixed-shoe-lot-used','black-everyday-shoes-used','blue-casual-shoes-used','retro-trainers-used','canvas-high-tops-used','daily-sneakers-used',
'apple-watch-series-5-used','vintage-silver-watch-used','classic-wrist-watch-used','watch-collection-used','quartz-everyday-watch-used','digital-sports-watch-used','apple-watch-se-used','mechanical-watch-used',
'pokemon-card-binder-used','hot-wheels-wall-used','hot-wheels-loose-lot-used','lego-bulk-lot-used','lego-organizer-used','board-game-shelf-used','toy-shelf-lot-used','vintage-game-boy-used')
and not exists (select 1 from public.price_history ph where ph.item_type_id=it.id);
